import { Worker } from "worker_threads";
import { EventEmitter } from "events";

export interface InvoiceJob {
  invoiceId: string;
  lines: { sku: string; qty: number; unitCents: number; taxRate: number }[];
  currency: string;
}

export interface InvoiceTotals {
  invoiceId: string;
  subtotalCents: number;
  taxCents: number;
  totalCents: number;
}

interface Task {
  job: InvoiceJob;
  resolve: (t: InvoiceTotals) => void;
  reject: (e: Error) => void;
}

export class InvoiceWorkerPool extends EventEmitter {
  private readonly idle: Worker[] = [];
  private readonly busy = new Map<Worker, Task>();
  private readonly queue: Task[] = [];
  private closed = false;

  constructor(private readonly script: string, size: number, private readonly maxQueue = 1000) {
    super();
    for (let i = 0; i < size; i++) this.idle.push(this.spawn());
  }

  compute(job: InvoiceJob): Promise<InvoiceTotals> {
    if (this.closed) return Promise.reject(new Error("pool closed"));
    if (this.queue.length >= this.maxQueue) {
      return Promise.reject(new Error("invoice pool saturated"));
    }
    return new Promise((resolve, reject) => {
      this.queue.push({ job, resolve, reject });
      this.drain();
    });
  }

  async close(): Promise<void> {
    this.closed = true;
    for (const t of this.queue.splice(0)) t.reject(new Error("pool closed"));
    await Promise.all([...this.idle, ...this.busy.keys()].map((w) => w.terminate()));
  }

  private spawn(): Worker {
    const worker = new Worker(this.script);
    worker.on("message", (totals: InvoiceTotals) => {
      const task = this.busy.get(worker);
      this.busy.delete(worker);
      this.idle.push(worker);
      task?.resolve(totals);
      this.drain();
    });
    worker.on("error", (err) => {
      this.busy.delete(worker);
      this.emit("workerError", err);
      if (!this.closed) this.idle.push(this.spawn());
      this.drain();
    });
    return worker;
  }

  private drain() {
    while (this.idle.length > 0 && this.queue.length > 0) {
      const worker = this.idle.pop()!;
      const task = this.queue.shift()!;
      this.busy.set(worker, task);
      worker.postMessage(task.job);
    }
  }
}

import { parentPort } from "worker_threads";
import type { InvoiceJob, InvoiceTotals } from "./invoicePool";

parentPort!.on("message", (job: InvoiceJob) => {
  let subtotal = 0;
  let tax = 0;
  for (const line of job.lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      throw new Error(`invalid quantity for ${line.sku} on ${job.invoiceId}`);
    }
    const amount = line.qty * line.unitCents;
    subtotal += amount;
    tax += Math.round(amount * line.taxRate);
  }
  const totals: InvoiceTotals = {
    invoiceId: job.invoiceId,
    subtotalCents: subtotal,
    taxCents: tax,
    totalCents: subtotal + tax,
  };
  parentPort!.postMessage(totals);
});

import os from "os";
import path from "path";
import { InvoiceWorkerPool, InvoiceJob } from "./invoicePool";

const pool = new InvoiceWorkerPool(
  path.join(__dirname, "invoiceWorker.js"),
  Math.max(1, os.cpus().length - 1),
);
pool.on("workerError", (err) => console.error(JSON.stringify({ msg: "invoice worker crashed", err: String(err) })));

export async function finalizeBillingRun(jobs: InvoiceJob[]) {
  const results = await Promise.allSettled(jobs.map((j) => pool.compute(j)));
  const failed = results.filter((r) => r.status === "rejected").length;
  return {
    finalized: results.flatMap((r) => (r.status === "fulfilled" ? [r.value] : [])),
    failed,
  };
}

process.on("SIGTERM", () => {
  void pool.close();
});
